    {
      "scene_number": 12,
      "caption": "The tower begins to collapse as they descend.",
      "visual_description": "Stones tumble from above, dust fills the stairwell, the group moves quickly downward in a tight line.",
      "characters": ["rescuer_leader", "scout", "mage", "captive"]
    },
    {
      "scene_number": 13,
      "caption": "Armored guards block the courtyard exit.",
      "visual_description": "Five guards form a shield wall across the courtyard archway, torches lighting their armor from below.",
      "characters": ["armored_patrol_guard_1", "armored_patrol_guard_2", "armored_patrol_guard_3", "armored_patrol_guard_4", "armored_patrol_guard_5", "rescuer_leader", "scout", "mage", "captive"]
    },
    {
      "scene_number": 14,
      "caption": "The mage creates a blinding flash to cover their escape.",
      "visual_description": "A white burst of light from the mage's hands, guards throwing up arms, the rescue party running past them into a side alley.",
      "characters": ["mage", "rescuer_leader", "scout", "captive", "armored_patrol_guard_1", "armored_patrol_guard_2", "armored_patrol_guard_3", "armored_patrol_guard_4", "armored_patrol_guard_5"]
    },
    {
      "scene_number": 15,
      "caption": "They race through a market square filled with abandoned stalls.",
      "visual_description": "Tipped wooden carts, rotting fruit, torn canvas awnings flapping in the wind, the group sprinting between the stalls.",
      "characters": ["rescuer_leader", "scout", "mage", "captive"]
    },
    {
      "scene_number": 16,
      "caption": "The bridge to safety appears ahead, but it is guarded.",
      "visual_description": "A long stone bridge spanning a dry riverbed, a single armored sentry standing at its midpoint beside a brazier.",
      "characters": ["bridge_sentry", "rescuer_leader", "scout", "mage", "captive"]
    },
    {
      "scene_number": 17,
      "caption": "The scout takes down the sentry with a precise shot.",
      "visual_description": "An arrow flies in silhouette across the bridge; the sentry staggers, hand reaching for the shaft, then falls over the railing.",
      "characters": ["scout", "bridge_sentry", "rescuer_leader", "mage", "captive"]
    },
    {
      "scene_number": 18,
      "caption": "The rescue party crosses the bridge into the free lands.",
      "visual_description": "The group runs across the bridge under a clearing sky, the ruined city behind them, open fields ahead lit by dawn.",
      "characters": ["rescuer_leader", "scout", "mage", "captive"]
    }
  ]
}

